-- CubeSat COTS component catalog — expanded taxonomy
-- Generated 31 Aug 2026
-- SQLite-compatible SQL
-- 326 catalog rows across 99 leaf topics.
-- Every leaf topic contains at least 3 COTS/reference options.
--
-- IMPORTANT:
-- "COTS" does not automatically mean flight-qualified.
-- Rows explicitly marked Engineering/Lab COTS require mission-specific
-- radiation, thermal-vacuum, vibration/shock, EMC, outgassing/materials,
-- contamination, reliability and/or biological containment qualification.
-- Integrated subsystems may appear under multiple tree leaves when one
-- commercial product legitimately provides several of those functions.

DROP TABLE IF EXISTS cubesat_cots;
CREATE TABLE cubesat_cots (
    id INTEGER PRIMARY KEY,
    tree_location TEXT NOT NULL,
    item_type TEXT NOT NULL,
    product_name TEXT NOT NULL,
    product_url TEXT,
    vendor TEXT,
    description TEXT,
    published_price TEXT,
    availability TEXT,
    procurement_class TEXT
);


CREATE INDEX IF NOT EXISTS idx_cubesat_tree_location ON cubesat_cots(tree_location);
CREATE INDEX IF NOT EXISTS idx_cubesat_item_type ON cubesat_cots(item_type);
CREATE INDEX IF NOT EXISTS idx_cubesat_procurement_class ON cubesat_cots(procurement_class);
CREATE INDEX IF NOT EXISTS idx_cubesat_vendor ON cubesat_cots(vendor);

DROP VIEW IF EXISTS cubesat_tree_coverage;
CREATE VIEW cubesat_tree_coverage AS
SELECT tree_location, item_type, COUNT(*) AS option_count
FROM cubesat_cots
GROUP BY tree_location, item_type
ORDER BY tree_location, item_type;
